using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_2b19ee07d7954871a34b1c4250a98685.Client;

namespace sv_2b19ee07d7954871a34b1c4250a98685;

// Runs on the server. Returns a hardcoded authenticated user and
// persists the identity into PersistentComponentState so the WASM
// client can pick it up after the render-mode handoff.
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private static readonly UserInfo _user = new()
    {
        Email = "bob@example.com",
        Roles = ["User", "Editor"]
    };

    private readonly PersistentComponentState _state;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    public ServerAuthenticationStateProvider(PersistentComponentState state)
    {
        _state = state;
        AuthenticationStateChanged += OnAuthenticationStateChanged;
        _subscription = _state.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, _user.Email),
            new(ClaimTypes.Email, _user.Email),
        };

        foreach (var role in _user.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        return Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
    }

    private void OnAuthenticationStateChanged(Task<AuthenticationState> task) => _authStateTask = task;

    private async Task OnPersistingAsync()
    {
        var authState = _authStateTask ?? GetAuthenticationStateAsync();
        var principal = (await authState).User;

        if (principal.Identity?.IsAuthenticated != true)
            return;

        _state.PersistAsJson(nameof(UserInfo), _user);
    }

    public void Dispose()
    {
        _subscription.Dispose();
        AuthenticationStateChanged -= OnAuthenticationStateChanged;
    }
}

